using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
namespace ShowOfHands.Tests {
 public class CodecTests {
  static string Samples=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../contract/samples"));
  [Test] public void AllReferenceSamplesDecodeAndRoundTrip(){foreach(var file in Directory.GetFiles(Samples,"*.clip.json")){var c=HandClip.FromJson(File.ReadAllText(file),out var error);Assert.That(c,Is.Not.Null,file+": "+error);var round=HandClip.FromJson(c.ToUploadJson("p_test"),out error);Assert.That(round,Is.Not.Null,error);CollectionAssert.AreEqual(c.Data,round.Data);}}
  [Test] public void WaveReferenceCoordinates(){var c=HandClip.FromJson(File.ReadAllText(Path.Combine(Samples,"wave.clip.json")),out _);Assert.That(Vector3.Distance(c.Joint(0,1,1),new Vector3(.220f,-.120f,.340f)),Is.LessThan(.00001f));Assert.That(Vector3.Distance(c.Joint(0,1,10),new Vector3(.204f,.061f,.351f)),Is.LessThan(.00001f));}
  [TestCase(72)] [TestCase(90)] public void RecorderResamplesTo240Frames(int hz){var frame=new HandFrame();frame.Right.Tracked=true;for(int j=0;j<26;j++)frame.Right.Joints[j]=new Vector3(.2f,-.2f,.3f);var r=new ClipRecorder{DetectRude=false};r.Begin(frame,8);for(int i=0;i<hz*8;i++)r.Push(frame,1f/hz);var clip=r.End("wave","ember","test","synthetic");Assert.That(clip.Frames,Is.EqualTo(240));Assert.That(clip.Data.Length,Is.EqualTo(240*328));Assert.That(clip.TrackedShare(),Is.EqualTo(1));}
  [Test] public void PinchHysteresisAndTrackingLoss(){var h=new HandState{Tracked=true};var d=new PinchDetector();h.Joints[10]=Vector3.right*.01f;d.Update(h);Assert.That(d.Began,Is.True);h.Joints[10]=Vector3.right*.025f;d.Update(h);Assert.That(d.Pinching,Is.True);Assert.That(d.Began,Is.False);h.Joints[10]=Vector3.right*.04f;d.Update(h);Assert.That(d.Pinching,Is.False);h.Tracked=false;d.Update(h);Assert.That(d.Began,Is.False);}
  [Test] public void PointerAnglesUseNearestCardPoint(){var go=new GameObject();try{go.transform.position=Vector3.forward;var target=new Target{Transform=go.transform,HalfSize=Vector2.one*.1f};Assert.That(Pointer.AngleTo(target,new Ray(Vector3.zero,Vector3.forward),out _),Is.EqualTo(0).Within(.001));Assert.That(Pointer.AngleTo(target,new Ray(Vector3.zero,Vector3.right),out _),Is.GreaterThan(80));}finally{Object.DestroyImmediate(go);}}
  [Test] public void TwoStationaryHandsNeverCountAsAWave(){var f=new HandFrame();f.Left.Tracked=f.Right.Tracked=true;f.Left.Joints[0]=new Vector3(-.2f,-.1f,.3f);f.Right.Joints[0]=new Vector3(.2f,-.1f,.3f);var detector=new WaveDetector();for(int i=0;i<500;i++)detector.Update(f);Assert.That(detector.Waved,Is.False);}
  [Test] public void SingleHandReversalsCountAsWave(){var f=new HandFrame();f.Right.Tracked=true;var detector=new WaveDetector();for(int i=0;i<360;i++){f.Right.Joints[0]=new Vector3(Mathf.Sin(i*.045f)*.15f,-.1f,.3f);detector.Update(f);}Assert.That(detector.Waved,Is.True);}
  [Test] public void RecorderLimitsDeviceMetadataForUpload(){var f=new HandFrame();f.Right.Tracked=true;var r=new ClipRecorder();r.Begin(f,1);for(int i=0;i<72;i++)r.Push(f,1f/72);var c=r.End("wave","ember",new string('a',60),new string('d',70));Assert.That(c.App.Length,Is.EqualTo(40));Assert.That(c.Device.Length,Is.EqualTo(40));}
  [Test] public void BundledSeedsHaveStableStoredMetadata(){var p=JsonUtility.FromJson<SeedPackJson>(File.ReadAllText(Path.Combine(Application.streamingAssetsPath,"seedpack.json")));var words=JsonUtility.FromJson<WordPack>(File.ReadAllText(Path.Combine(Application.streamingAssetsPath,"words.json")));foreach(var c in p.clips){Assert.That(c.id.Length,Is.EqualTo(6));Assert.That(c.by.Length,Is.EqualTo(5));Assert.That(c.created,Is.Not.Empty);Assert.That(c.options.Length,Is.EqualTo(4));Assert.That(c.options.Distinct().Count(),Is.EqualTo(4));Assert.That(c.options,Does.Contain(c.word));foreach(var id in c.options)Assert.That(words.words.Any(w=>w.id==id),Is.True,id);}}
 }
}
